/** Units of time. */
export type TimeUnitType = 'ns' | 'µs' | 'ms' | 's' | 'min' | 'h' | 'd' | 'mo' | 'y';
/** Units of data in bits */
export type DataUnitBitType = 'bit' | 'kbit' | 'Mbit' | 'Gbit' | 'Tbit' | 'Pbit';
/** Units of data in bytes */
export type DataUnitByteType = 'byte' | 'kB' | 'MB' | 'GB' | 'TB' | 'PB';
/** Units of data. */
export type DataUnitType = DataUnitBitType & DataUnitByteType;
/** Units of exponential numbers, i.e. kilo, million, ect. */
export type ExponentialNumberUnitType = 'K' | 'M' | 'B' | 'T';
/** Conversion factors for all time units to nanosecond */
export declare const TimeConversionFactors: Array<{
    multiplier: number;
    postfix: TimeUnitType;
}>;
/**
 * Levels of abbreviations for decimal exponents from kilo to trillion,
 * 10^3, 10^6, ...
 */
export declare const ExponentialDecimalLevels: Array<{
    multiplier: number;
    postfix: ExponentialNumberUnitType;
}>;
/**
 * Levels of abbreviation for octal bit exponents from kilobit to petabits,
 * 2^10, 2^20, 2^30...
 */
export declare const ExponentialOctalBitLevels: Array<{
    multiplier: number;
    postfix: DataUnitBitType;
}>;
/**
 * Levels of abbreviation for octal byte exponents from kilobyte to petabyte,
 * 2^10, 2^20, 2^30...
 */
export declare const ExponentialOctalByteLevels: Array<{
    multiplier: number;
    postfix: DataUnitByteType;
}>;
